export const ERASED_EMAIL = 'erased@customer.invalid';
export const ERASED_NAME = 'Erased Customer';
export const ERASED_PHONE = null;
export const ERASED_EXTERNAL_REFERENCE_PREFIX = 'erased:';
export const ERASED_TEXT = '[erased]';
export const ERASED_ADDRESS_LINE = '[erased]';
export const ERASED_CITY = '[erased]';
export const ERASED_POSTAL = '00000';
export const ERASED_COUNTRY = 'XX';

export function erasedExternalReference(customerId: string): string {
  return `${ERASED_EXTERNAL_REFERENCE_PREFIX}${customerId}`;
}

export function anonymizedCustomerSnapshot(customerId: string): Record<string, unknown> {
  return {
    id: customerId,
    email: ERASED_EMAIL,
    name: ERASED_NAME,
    phone: ERASED_PHONE,
    external_reference: erasedExternalReference(customerId),
    status: 'erased',
    metadata: {},
  };
}

/** Removes known PII keys from unstructured JSON while keeping structural/financial fields. */
export function scrubJsonValue(value: unknown): unknown {
  if (Array.isArray(value)) return value.map((entry) => scrubJsonValue(entry));
  if (!value || typeof value !== 'object') return value;
  const input = value as Record<string, unknown>;
  const output: Record<string, unknown> = {};
  for (const [key, entry] of Object.entries(input)) {
    const lower = key.toLowerCase();
    if (
      lower.includes('email')
      || lower.includes('phone')
      || lower === 'name'
      || lower.endsWith('name')
      || lower.includes('billing_name')
      || lower.includes('displayname')
      || lower.includes('display_name')
      || lower.includes('line1')
      || lower.includes('line2')
      || lower.includes('address')
      || lower.includes('postal')
      || lower === 'city'
      || lower === 'region'
      || lower === 'destination'
      || lower === 'body'
      || lower === 'subject'
      || lower === 'text'
      || lower === 'html'
      || lower === 'text_body'
      || lower === 'html_body'
      || lower === 'provider_token'
      || lower === 'providertoken'
      || lower === 'external_reference'
      || lower === 'externalreference'
    ) {
      if (lower.includes('email') || lower === 'destination') output[key] = ERASED_EMAIL;
      else if (lower.includes('phone')) output[key] = ERASED_PHONE;
      else if (lower.includes('name')) output[key] = ERASED_NAME;
      else if (lower.includes('country')) output[key] = ERASED_COUNTRY;
      else if (lower.includes('postal')) output[key] = ERASED_POSTAL;
      else if (lower === 'external_reference' || lower === 'externalreference') {
        output[key] = typeof entry === 'string' && entry.startsWith(ERASED_EXTERNAL_REFERENCE_PREFIX)
          ? entry
          : erasedExternalReference(String(input.customerId ?? input.customer_id ?? 'unknown'));
      } else if (typeof entry === 'object' && entry !== null) {
        output[key] = scrubJsonValue(entry);
      } else {
        output[key] = ERASED_TEXT;
      }
      continue;
    }
    output[key] = scrubJsonValue(entry);
  }
  return output;
}
