{"command":"create","path":"/workspace/source/packages/privacy/src/erasure-repository.ts","file_text":"import type pg from 'pg';
import { pool } from '../../database/src/pool.js';

export type ErasureStatus = 'pending' | 'processing' | 'failed' | 'completed';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: ErasureStatus;
  attempts: number;
  last_error: string | null;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

export interface ErasureRequestResponse {
  id: string;
  customerId: string;
  status: ErasureStatus;
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

export function toErasureResponse(row: ErasureRequestRow): ErasureRequestResponse {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error,
  };
}

export class ErasureRepository {
  async findCustomer(merchantId: string, customerId: string): Promise<{ id: string } | undefined> {
    const result = await pool.query<{ id: string }>(
      `SELECT id FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async findById(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async findByCustomer(merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async createRequest(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
  ): Promise<ErasureRequestRow> {
    const result = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id,customer_id,status)
       VALUES($1,$2,'pending')
       ON CONFLICT(merchant_id,customer_id) DO UPDATE
         SET updated_at=customers.erasure_requests.updated_at
       RETURNING *`,
      [merchantId, customerId],
    );
    return result.rows[0]!;
  }

  async enqueueJob(
    client: pg.PoolClient,
    merchantId: string,
    requestId: string,
    customerId: string,
  ): Promise<void> {
    const existing = await client.query(
      `SELECT 1 FROM operations.jobs
       WHERE queue='privacy' AND job_type='customer_erasure'
         AND merchant_id=$1
         AND payload->>'requestId'=$2
         AND status IN ('pending','retry','processing')
       LIMIT 1`,
      [merchantId, requestId],
    );
    if (existing.rowCount) return;
    await client.query(
      `INSERT INTO operations.jobs(queue,job_type,merchant_id,payload,status,max_attempts)
       VALUES('privacy','customer_erasure',$1,$2,'pending',16)`,
      [merchantId, { requestId, customerId, merchantId }],
    );
  }

  async markProcessing(client: pg.PoolClient, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status='processing', attempts=attempts+1, updated_at=now(), last_error=NULL
       WHERE id=$1 AND status IN ('pending','failed','processing')
       RETURNING *`,
      [requestId],
    );
    return result.rows[0];
  }

  async markCompleted(client: pg.PoolClient, requestId: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='completed', updated_at=now(), completed_at=COALESCE(completed_at, now()), last_error=NULL
       WHERE id=$1`,
      [requestId],
    );
  }

  async markFailed(client: pg.PoolClient, requestId: string, errorCode: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='failed', updated_at=now(), last_error=$2
       WHERE id=$1 AND status <> 'completed'`,
      [requestId, errorCode],
    );
  }

  async isStepComplete(client: pg.PoolClient, requestId: string, step: string): Promise<boolean> {
    const result = await client.query(
      `SELECT 1 FROM customers.erasure_step_completions
       WHERE erasure_request_id=$1 AND step=$2`,
      [requestId, step],
    );
    return Boolean(result.rowCount);
  }

  async completeStep(client: pg.PoolClient, requestId: string, step: string): Promise<void> {
    await client.query(
      `INSERT INTO customers.erasure_step_completions(erasure_request_id,step)
       VALUES($1,$2) ON CONFLICT DO NOTHING`,
      [requestId, step],
    );
  }

  async ensureTombstone(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
    requestId: string,
  ): Promise<void> {
    await client.query(
      `INSERT INTO customers.erasure_tombstones(merchant_id,customer_id,erasure_request_id)
       VALUES($1,$2,$3)
       ON CONFLICT(merchant_id,customer_id) DO NOTHING`,
      [merchantId, customerId, requestId],
    );
  }

  async hasTombstone(merchantId: string, customerId: string): Promise<boolean> {
    const result = await pool.query(
      `SELECT 1 FROM customers.erasure_tombstones WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return Boolean(result.rowCount);
  }

  async hasTombstoneClient(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
  ): Promise<boolean> {
    const result = await client.query(
      `SELECT 1 FROM customers.erasure_tombstones WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return Boolean(result.rowCount);
  }
}
"}

{"command":"create","path":"/workspace/source/packages/privacy/src/erasure-executor.ts","file_text":"import { createHash } from 'node:crypto';
import type pg from 'pg';
import { Redis } from 'ioredis';
import { config } from '../../config/src/index.js';
import { transaction } from '../../database/src/pool.js';
import { deleteMailpitMessagesForRecipient } from '../../notifications/src/mailpit.js';
import { CUSTOMER_INDEX, searchClient } from '../../search/src/client.js';
import { DOCUMENT_BUCKET, ensureBucket, objectStore } from '../../storage/src/minio.js';
import {
  ERASED_COUNTRY,
  ERASED_EMAIL,
  ERASED_NAME,
  ERASED_PHONE,
  ERASED_POSTAL,
  ERASED_TEXT,
  anonymizedCustomerSnapshot,
  erasedExternalReference,
  scrubJsonValue,
} from './redaction.js';
import { ErasureRepository } from './erasure-repository.js';

const STEPS = [
  'capture_destinations',
  'tombstone',
  'customer_core',
  'payments',
  'operations',
  'documents',
  'search_cache',
  'provider',
  'mail',
  'finalize',
] as const;

type StepName = (typeof STEPS)[number];

interface ErasureContext {
  requestId: string;
  merchantId: string;
  customerId: string;
  destinations: string[];
}

function stableErrorCode(error: unknown): string {
  if (!(error instanceof Error)) return 'erasure_failed';
  const message = error.message.toLowerCase();
  if (message.includes('mailpit')) return 'mail_cleanup_failed';
  if (message.includes('opensearch') || message.includes('search')) return 'search_cleanup_failed';
  if (message.includes('minio') || message.includes('s3') || message.includes('object')) {
    return 'document_cleanup_failed';
  }
  if (message.includes('redis')) return 'cache_cleanup_failed';
  return 'erasure_failed';
}

async function listObjectKeys(prefix: string): Promise<string[]> {
  await ensureBucket();
  const keys: string[] = [];
  await new Promise<void>((resolve, reject) => {
    const stream = objectStore.listObjectsV2(DOCUMENT_BUCKET, prefix, true);
    stream.on('data', (item) => {
      if (item.name) keys.push(item.name);
    });
    stream.on('error', reject);
    stream.on('end', resolve);
  });
  return keys;
}

async function putJsonObject(objectKey: string, body: unknown): Promise<string> {
  const content = JSON.stringify(body);
  await objectStore.putObject(
    DOCUMENT_BUCKET,
    objectKey,
    content,
    Buffer.byteLength(content),
    { 'Content-Type': 'application/json' },
  );
  return createHash('sha256').update(content).digest('hex');
}

async function deleteObjectQuietly(objectKey: string): Promise<void> {
  try {
    await objectStore.removeObject(DOCUMENT_BUCKET, objectKey);
  } catch {
    // Object may already be gone; treat as success for idempotent cleanup.
  }
}

export class ErasureExecutor {
  constructor(private readonly repository = new ErasureRepository()) {}

  async execute(requestId: string, merchantId: string, customerId: string): Promise<void> {
    const context: ErasureContext = {
      requestId,
      merchantId,
      customerId,
      destinations: [],
    };

    try {
      await transaction(async (client) => {
        const row = await this.repository.markProcessing(client, requestId);
        if (!row) {
          const current = await client.query<{ status: string }>(
            `SELECT status FROM customers.erasure_requests WHERE id=$1 AND merchant_id=$2`,
            [requestId, merchantId],
          );
          if (current.rows[0]?.status === 'completed') return;
          throw Object.assign(new Error('erasure_request_not_found'), { statusCode: 404 });
        }
      });

      for (const step of STEPS) {
        await this.runStep(context, step);
      }
    } catch (error) {
      const code = stableErrorCode(error);
      await transaction(async (client) => {
        await this.repository.markFailed(client, requestId, code);
      });
      throw Object.assign(error instanceof Error ? error : new Error(String(error)), {
        erasureErrorCode: code,
      });
    }
  }

  private async runStep(context: ErasureContext, step: StepName): Promise<void> {
    const alreadyDone = await transaction(async (client) =>
      this.repository.isStepComplete(client, context.requestId, step));
    if (alreadyDone && step !== 'capture_destinations' && step !== 'finalize') return;

    switch (step) {
      case 'capture_destinations':
        context.destinations = await this.captureDestinations(context);
        break;
      case 'tombstone':
        await this.writeTombstone(context);
        break;
      case 'customer_core':
        await this.eraseCustomerCore(context);
        break;
      case 'payments':
        await this.erasePayments(context);
        break;
      case 'operations':
        await this.eraseOperations(context);
        break;
      case 'documents':
        await this.eraseDocuments(context);
        break;
      case 'search_cache':
        await this.eraseSearchAndCache(context);
        break;
      case 'provider':
        await this.eraseProvider(context);
        break;
      case 'mail':
        await this.eraseMail(context);
        break;
      case 'finalize':
        await this.finalize(context);
        break;
      default:
        break;
    }

    if (step !== 'finalize') {
      await transaction(async (client) => {
        await this.repository.completeStep(client, context.requestId, step);
      });
    }
  }

  private async captureDestinations(context: ErasureContext): Promise<string[]> {
    return transaction(async (client) => {
      if (await this.repository.isStepComplete(client, context.requestId, 'capture_destinations')) {
        const stored = await client.query<{ destinations: string[] }>(
          `SELECT COALESCE(metadata->'destinations', '[]'::jsonb) AS destinations
           FROM platform.audit_logs
           WHERE merchant_id=$1 AND target_id=$2 AND action='customer.erasure.destinations'
           ORDER BY created_at DESC LIMIT 1`,
          [context.merchantId, context.customerId],
        );
        if (stored.rows[0]?.destinations) {
          return stored.rows[0].destinations;
        }
      }

      const destinations = new Set<string>();
      const customer = await client.query<{ email: string | null; phone: string | null }>(
        `SELECT email, phone FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
        [context.merchantId, context.customerId],
      );
      if (customer.rows[0]?.email) destinations.add(customer.rows[0].email);
      if (customer.rows[0]?.phone) destinations.add(customer.rows[0].phone);

      const contacts = await client.query<{ value: string }>(
        `SELECT value FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`,
        [context.merchantId, context.customerId],
      );
      for (const row of contacts.rows) destinations.add(row.value);

      const prefs = await client.query<{ destination: string }>(
        `SELECT destination FROM operations.notification_preferences
         WHERE merchant_id=$1 AND customer_id=$2`,
        [context.merchantId, context.customerId],
      );
      for (const row of prefs.rows) destinations.add(row.destination);

      const emails = await client.query<{ destination: string }>(
        `SELECT destination FROM operations.email_deliveries
         WHERE merchant_id=$1 AND customer_id=$2`,
        [context.merchantId, context.customerId],
      );
      for (const row of emails.rows) destinations.add(row.destination);

      const notifications = await client.query<{ destination: string }>(
        `SELECT destination FROM operations.notifications
         WHERE merchant_id=$1 AND customer_id=$2`,
        [context.merchantId, context.customerId],
      );
      for (const row of notifications.rows) destinations.add(row.destination);

      const snapshots = await client.query<{ email: string | null }>(
        `SELECT customer_snapshot->>'email' AS email
         FROM payments.payment_intents
         WHERE merchant_id=$1 AND customer_id=$2`,
        [context.merchantId, context.customerId],
      );
      for (const row of snapshots.rows) if (row.email) destinations.add(row.email);

      const refunds = await client.query<{ customer_email: string | null }>(
        `SELECT customer_email FROM payments.refunds r
         JOIN payments.payment_intents p ON p.id=r.payment_intent_id
         WHERE r.merchant_id=$1 AND p.customer_id=$2`,
        [context.merchantId, context.customerId],
      );
      for (const row of refunds.rows) if (row.customer_email) destinations.add(row.customer_email);

      const list = [...destinations].filter((value) => value && value !== ERASED_EMAIL);
      await client.query(
        `INSERT INTO platform.audit_logs
         (merchant_id,actor_type,target_type,target_id,action,metadata,correlation_id)
         VALUES($1,'system','customer',$2,'customer.erasure.destinations',$3,gen_random_uuid())`,
        [context.merchantId, context.customerId, { destinations: list, requestId: context.requestId }],
      );
      return list;
    });
  }

  private async writeTombstone(context: ErasureContext): Promise<void> {
    await transaction(async (client) => {
      await this.repository.ensureTombstone(
        client,
        context.merchantId,
        context.customerId,
        context.requestId,
      );
    });
  }

  private async eraseCustomerCore(context: ErasureContext): Promise<void> {
    await transaction(async (client) => {
      await client.query(
        `UPDATE customers.customers
         SET email=$3, name=$4, phone=$5, external_reference=$6, metadata='{}'::jsonb,
             status='erased', version=version+1, updated_at=now()
         WHERE merchant_id=$1 AND id=$2`,
        [
          context.merchantId,
          context.customerId,
          ERASED_EMAIL,
          ERASED_NAME,
          ERASED_PHONE,
          erasedExternalReference(context.customerId),
        ],
      );

      await client.query(
        `UPDATE customers.addresses
         SET line1=$3, line2=NULL, city=$3, region=NULL, postal_code=$4, country=$5
         WHERE merchant_id=$1 AND customer_id=$2`,
        [context.merchantId, context.customerId, ERASED_TEXT, ERASED_POSTAL, ERASED_COUNTRY],
      );

      await client.query(
        `UPDATE customers.contacts
         SET value=$3, is_primary=false, verified_at=NULL
         WHERE merchant_id=$1 AND customer_id=$2`,
        [context.merchantId, context.customerId, ERASED_EMAIL],
      );

      await client.query(
        `UPDATE customers.payment_method_refs
         SET provider_token=$3, brand=NULL, last4=NULL, billing_name=$4,
             billing_address='{}'::jsonb, status='erased'
         WHERE merchant_id=$1 AND customer_id=$2`,
        [context.merchantId, context.customerId, `erased_${context.customerId}`, ERASED_NAME],
      );

      // Support tickets may be shared. Remove this customer as participant and
      // redact only messages authored by them. Leave other participants intact.
      const tickets = await client.query<{ ticket_id: string }>(
        `SELECT ticket_id FROM customers.support_participants WHERE customer_id=$1`,
        [context.customerId],
      );
      for (const ticket of tickets.rows) {
        await client.query(
          `DELETE FROM customers.support_participants WHERE ticket_id=$1 AND customer_id=$2`,
          [ticket.ticket_id, context.customerId],
        );
        await client.query(
          `UPDATE customers.support_messages
           SET body=$3, attachments='[]'::jsonb
           WHERE merchant_id=$1 AND ticket_id=$2 AND author_type='customer' AND author_id=$4`,
          [context.merchantId, ticket.ticket_id, ERASED_TEXT, context.customerId],
        );
        const remaining = await client.query(
          `SELECT 1 FROM customers.support_participants WHERE ticket_id=$1 LIMIT 1`,
          [ticket.ticket_id],
        );
        if (!remaining.rowCount) {
          await client.query(
            `UPDATE customers.support_messages SET body=$2, attachments='[]'::jsonb WHERE ticket_id=$1`,
            [ticket.ticket_id, ERASED_TEXT],
          );
          await client.query(
            `UPDATE customers.support_tickets SET subject=$2 WHERE id=$1 AND merchant_id=$3`,
            [ticket.ticket_id, ERASED_TEXT, context.merchantId],
          );
        }
      }

      await client.query(
        `UPDATE platform.audit_logs
         SET metadata=$3
         WHERE merchant_id=$1 AND target_type='customer' AND target_id=$2
           AND action <> 'customer.erasure.destinations'`,
        [context.merchantId, context.customerId, { erased: true }],
      );

      // Customer-import artifacts tied only through manifests / object keys are handled in documents.
    });
  }

  private async erasePayments(context: ErasureContext): Promise<void> {
    const snapshot = anonymizedCustomerSnapshot(context.customerId);
    await transaction(async (client) => {
      await client.query(
        `UPDATE payments.payment_intents
         SET customer_snapshot=$3, description=CASE
           WHEN description IS NULL THEN NULL ELSE $4 END, updated_at=now()
         WHERE merchant_id=$1 AND customer_id=$2`,
        [context.merchantId, context.customerId, snapshot, ERASED_TEXT],
      );

      await client.query(
        `UPDATE payments.payment_attempts a
         SET request_payload=$3, response_payload=CASE
           WHEN response_payload IS NULL THEN NULL ELSE $3 END,
             failure_message=CASE WHEN failure_message IS NULL THEN NULL ELSE $4 END
         FROM payments.payment_intents p
         WHERE a.payment_intent_id=p.id AND p.merchant_id=$1 AND p.customer_id=$2`,
        [context.merchantId, context.customerId, scrubJsonValue({ customerId: context.customerId }), ERASED_TEXT],
      );

      await client.query(
        `UPDATE payments.refunds r
         SET customer_email=$3
         FROM payments.payment_intents p
         WHERE r.payment_intent_id=p.id AND r.merchant_id=$1 AND p.customer_id=$2`,
        [context.merchantId, context.customerId, ERASED_EMAIL],
      );

      await client.query(
        `UPDATE payments.disputes d
         SET evidence=$3
         FROM payments.payment_intents p
         WHERE d.payment_intent_id=p.id AND d.merchant_id=$1 AND p.customer_id=$2`,
        [context.merchantId, context.customerId, scrubJsonValue({})],
      );

      await client.query(
        `UPDATE payments.invoices
         SET billing_snapshot=$3
         WHERE merchant_id=$1 AND customer_id=$2`,
        [context.merchantId, context.customerId, snapshot],
      );

      // Ledger entries keep financial meaning; scrub only free-text descriptions that may embed names.
      await client.query(
        `UPDATE payments.ledger_entries e
         SET description=$3
         FROM payments.payment_intents p
         WHERE e.merchant_id=$1
           AND (
             (e.reference_type IN ('capture','payment_intent') AND e.reference_id=p.id)
             OR (e.reference_type='refund' AND e.reference_id IN (
               SELECT r.id FROM payments.refunds r WHERE r.payment_intent_id=p.id
             ))
           )
           AND p.customer_id=$2`,
        [context.merchantId, context.customerId, ERASED_TEXT],
      );
    });
  }

  private async eraseOperations(context: ErasureContext): Promise<void> {
    await transaction(async (client) => {
      await client.query(
        `UPDATE operations.outbox_events
         SET payload=$3
         WHERE merchant_id=$1
           AND (
             aggregate_id=$2
             OR payload->>'customerId'=$2
             OR payload->>'customer_id'=$2
           )`,
        [context.merchantId, context.customerId, scrubJsonValue({ customerId: context.customerId, erased: true })],
      );

      await client.query(
        `UPDATE operations.analytics_events
         SET email=$3, properties=$4, anonymous_id=$5
         WHERE merchant_id=$1 AND customer_id=$2`,
        [
          context.merchantId,
          context.customerId,
          ERASED_EMAIL,
          scrubJsonValue({ customerId: context.customerId, erased: true }),
          `anon_erased_${context.customerId}`,
        ],
      );

      await client.query(
        `DELETE FROM operations.notification_preferences
         WHERE merchant_id=$1 AND customer_id=$2`,
        [context.merchantId, context.customerId],
      );

      await client.query(
        `UPDATE operations.email_deliveries
         SET destination=$3, subject=$4, text_body=$4, html_body=$4,
             status=CASE WHEN status='pending' THEN 'cancelled' ELSE status END,
             cancelled_at=CASE WHEN status='pending' THEN now() ELSE cancelled_at END
         WHERE merchant_id=$1 AND customer_id=$2`,
        [context.merchantId, context.customerId, ERASED_EMAIL, ERASED_TEXT],
      );

      await client.query(
        `UPDATE operations.notifications
         SET destination=$3, payload=$4, status=CASE
           WHEN status IN ('queued','retrying') THEN 'cancelled' ELSE status END
         WHERE merchant_id=$1 AND customer_id=$2`,
        [
          context.merchantId,
          context.customerId,
          ERASED_EMAIL,
          scrubJsonValue({ customerId: context.customerId, erased: true }),
        ],
      );

      await client.query(
        `UPDATE operations.jobs
         SET payload=$3
         WHERE merchant_id=$1
           AND (
             payload->>'customerId'=$2
             OR payload->>'customer_id'=$2
           )
           AND job_type <> 'customer_erasure'`,
        [
          context.merchantId,
          context.customerId,
          scrubJsonValue({ customerId: context.customerId, erased: true }),
        ],
      );

      await client.query(
        `UPDATE operations.dead_letters
         SET payload=$2
         WHERE payload->>'customerId'=$1 OR payload->>'customer_id'=$1`,
        [context.customerId, scrubJsonValue({ customerId: context.customerId, erased: true })],
      );

      await client.query(
        `UPDATE operations.idempotency_keys
         SET response_body=CASE WHEN response_body IS NULL THEN NULL ELSE $3 END
         WHERE merchant_id=$1
           AND (
             response_body->>'customerId'=$2
             OR response_body->>'customer_id'=$2
           )`,
        [context.merchantId, context.customerId, scrubJsonValue({ customerId: context.customerId, erased: true })],
      );
    });
  }

  private async eraseDocuments(context: ErasureContext): Promise<void> {
    const manifests = await transaction(async (client) => {
      const result = await client.query<{
        id: string;
        object_key: string;
        document_type: string;
        metadata: Record<string, unknown>;
      }>(
        `SELECT id, object_key, document_type, metadata
         FROM operations.document_manifests
         WHERE merchant_id=$1 AND customer_id=$2`,
        [context.merchantId, context.customerId],
      );
      return result.rows;
    });

    for (const manifest of manifests) {
      if (manifest.document_type === 'customer_import') {
        await deleteObjectQuietly(manifest.object_key);
        await transaction(async (client) => {
          await client.query(
            `DELETE FROM operations.document_manifests WHERE id=$1`,
            [manifest.id],
          );
          await client.query(
            `UPDATE customers.customer_imports
             SET object_key=$3, status='erased'
             WHERE merchant_id=$1 AND object_key=$2`,
            [context.merchantId, manifest.object_key, `erased/${context.customerId}/${manifest.id}`],
          );
        });
        continue;
      }

      const anonymized = {
        erased: true,
        customerId: context.customerId,
        documentType: manifest.document_type,
        metadata: scrubJsonValue(manifest.metadata),
        customer: anonymizedCustomerSnapshot(context.customerId),
      };
      const checksum = await putJsonObject(manifest.object_key, anonymized);
      await transaction(async (client) => {
        await client.query(
          `UPDATE operations.document_manifests
           SET checksum=$2, metadata=$3, customer_id=$4
           WHERE id=$1`,
          [
            manifest.id,
            checksum,
            scrubJsonValue({ ...manifest.metadata, erased: true }),
            context.customerId,
          ],
        );
      });
    }

    // Scrub any remaining import rows without manifests.
    await transaction(async (client) => {
      const imports = await client.query<{ id: string; object_key: string }>(
        `SELECT id, object_key FROM customers.customer_imports WHERE merchant_id=$1`,
        [context.merchantId],
      );
      for (const row of imports.rows) {
        if (row.object_key.includes(context.customerId) || row.object_key.includes('/imports/')) {
          // Only touch imports whose stored object mentions this customer.
          try {
            const stream = await objectStore.getObject(DOCUMENT_BUCKET, row.object_key);
            const chunks: Buffer[] = [];
            for await (const chunk of stream) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
            const raw = Buffer.concat(chunks).toString('utf8');
            if (raw.includes(context.customerId)) {
              await deleteObjectQuietly(row.object_key);
              await client.query(
                `UPDATE customers.customer_imports SET object_key=$2, status='erased' WHERE id=$1`,
                [row.id, `erased/${context.customerId}/${row.id}`],
              );
              await client.query(
                `DELETE FROM operations.document_manifests WHERE object_key=$1`,
                [row.object_key],
              );
            }
          } catch {
            // Missing object is fine.
          }
        }
      }
    });
  }

  private async eraseSearchAndCache(context: ErasureContext): Promise<void> {
    try {
      await searchClient.delete({
        index: CUSTOMER_INDEX,
        id: `${context.merchantId}:${context.customerId}`,
        refresh: true,
      });
    } catch (error) {
      const statusCode = (error as { meta?: { statusCode?: number } }).meta?.statusCode;
      if (statusCode !== 404) throw error;
    }

    const redis = new Redis(config().REDIS_URL);
    try {
      const rootKey = `merchant:${context.merchantId}:customer:${context.customerId}`;
      await redis.del(rootKey, `${rootKey}:activity`);
    } finally {
      redis.disconnect();
    }
  }

  private async eraseProvider(context: ErasureContext): Promise<void> {
    await transaction(async (client) => {
      await client.query(
        `DELETE FROM provider_sandbox.customers
         WHERE merchant_id=$1 AND payflow_customer_id=$2`,
        [context.merchantId, context.customerId],
      );
      await client.query(
        `DELETE FROM customers.provider_customer_mappings
         WHERE merchant_id=$1 AND customer_id=$2`,
        [context.merchantId, context.customerId],
      );
    });
  }

  private async eraseMail(context: ErasureContext): Promise<void> {
    for (const destination of context.destinations) {
      if (!destination.includes('@')) continue;
      await deleteMailpitMessagesForRecipient(destination);
    }
    await deleteMailpitMessagesForRecipient(ERASED_EMAIL);
  }

  private async finalize(context: ErasureContext): Promise<void> {
    await transaction(async (client) => {
      await this.repository.completeStep(client, context.requestId, 'finalize');
      await this.repository.markCompleted(client, context.requestId);
      await client.query(
        `INSERT INTO platform.audit_logs
         (merchant_id,actor_type,target_type,target_id,action,metadata,correlation_id)
         VALUES($1,'system','customer',$2,'customer.erasure.completed',$3,gen_random_uuid())`,
        [context.merchantId, context.customerId, { requestId: context.requestId }],
      );
    });
  }
}

export { stableErrorCode };
"}

{"command":"create","path":"/workspace/source/packages/privacy/src/erasure-service.ts","file_text":"import { transaction } from '../../database/src/pool.js';
import {
  ErasureRepository,
  toErasureResponse,
  type ErasureRequestResponse,
} from './erasure-repository.js';

const IDEMPOTENCY_SCOPE = 'customer-erasure';

export class ErasureService {
  constructor(private readonly repository = new ErasureRepository()) {}

  async createOrResume(
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<{ status: number; body: ErasureRequestResponse }> {
    const customer = await this.repository.findCustomer(merchantId, customerId);
    if (!customer) {
      throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });
    }

    return transaction(async (client) => {
      const existingForCustomer = await client.query(
        `SELECT * FROM customers.erasure_requests
         WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
        [merchantId, customerId],
      );
      if (existingForCustomer.rows[0]) {
        const row = existingForCustomer.rows[0];
        await this.repository.enqueueJob(client, merchantId, row.id, customerId);
        // Bind idempotency key to this existing request when first seen.
        await client.query(
          `INSERT INTO operations.idempotency_keys
           (merchant_id,scope,key,request_hash,response_status,response_body,expires_at)
           VALUES($1,$2,$3,$4,$5,$6,now()+interval '30 days')
           ON CONFLICT(merchant_id,scope,key) DO NOTHING`,
          [
            merchantId,
            IDEMPOTENCY_SCOPE,
            idempotencyKey,
            customerId,
            202,
            toErasureResponse(row),
          ],
        );
        const keyRow = await client.query<{ request_hash: string; response_body: ErasureRequestResponse }>(
          `SELECT request_hash, response_body FROM operations.idempotency_keys
           WHERE merchant_id=$1 AND scope=$2 AND key=$3`,
          [merchantId, IDEMPOTENCY_SCOPE, idempotencyKey],
        );
        if (keyRow.rows[0] && keyRow.rows[0].request_hash !== customerId) {
          throw Object.assign(new Error('idempotency key reused with different customer'), {
            statusCode: 409,
          });
        }
        return { status: 202, body: toErasureResponse(row) };
      }

      const existingKey = await client.query<{
        request_hash: string;
        response_status: number | null;
        response_body: ErasureRequestResponse | null;
      }>(
        `SELECT request_hash, response_status, response_body
         FROM operations.idempotency_keys
         WHERE merchant_id=$1 AND scope=$2 AND key=$3 FOR UPDATE`,
        [merchantId, IDEMPOTENCY_SCOPE, idempotencyKey],
      );
      if (existingKey.rows[0]) {
        const row = existingKey.rows[0];
        if (row.request_hash !== customerId) {
          throw Object.assign(new Error('idempotency key reused with different customer'), {
            statusCode: 409,
          });
        }
        if (row.response_status !== null && row.response_body) {
          return { status: row.response_status, body: row.response_body };
        }
      }

      const created = await this.repository.createRequest(client, merchantId, customerId);
      await this.repository.enqueueJob(client, merchantId, created.id, customerId);
      const body = toErasureResponse(created);
      await client.query(
        `INSERT INTO operations.idempotency_keys
         (merchant_id,scope,key,request_hash,response_status,response_body,expires_at)
         VALUES($1,$2,$3,$4,202,$5,now()+interval '30 days')
         ON CONFLICT(merchant_id,scope,key) DO UPDATE
           SET response_status=EXCLUDED.response_status,
               response_body=EXCLUDED.response_body,
               request_hash=EXCLUDED.request_hash
         WHERE operations.idempotency_keys.request_hash=EXCLUDED.request_hash`,
        [merchantId, IDEMPOTENCY_SCOPE, idempotencyKey, customerId, body],
      );
      await client.query(
        `INSERT INTO platform.audit_logs
         (merchant_id,actor_type,target_type,target_id,action,metadata,correlation_id)
         VALUES($1,'api_key','customer',$2,'customer.erasure.requested',$3,gen_random_uuid())`,
        [merchantId, customerId, { requestId: created.id }],
      );
      return { status: 202, body };
    });
  }

  async get(merchantId: string, requestId: string): Promise<ErasureRequestResponse> {
    const row = await this.repository.findById(merchantId, requestId);
    if (!row) throw Object.assign(new Error('erasure_request_not_found'), { statusCode: 404 });
    return toErasureResponse(row);
  }
}
"}

{"command":"create","path":"/workspace/source/apps/erasure-worker/src/main.ts","file_text":"import { randomUUID } from 'node:crypto';
import { logger } from '../../../packages/observability/src/logger.js';
import {
  claimJob,
  completeJob,
  failJob,
  recoverExpiredJobLeases,
  type ClaimedJob,
} from '../../../packages/operations/src/job-lifecycle.js';
import { transaction } from '../../../packages/database/src/pool.js';
import { ErasureExecutor } from '../../../packages/privacy/src/erasure-executor.js';

process.env.SERVICE_NAME = 'erasure-worker';

interface ErasureJobPayload {
  requestId: string;
  customerId: string;
  merchantId: string;
}

const workerId = `erasure-worker-${randomUUID()}`;
const controller = new AbortController();
const executor = new ErasureExecutor();

async function processJob(job: ClaimedJob<ErasureJobPayload>): Promise<void> {
  const payload = job.payload;
  await executor.execute(payload.requestId, payload.merchantId ?? job.merchant_id, payload.customerId);
  await transaction(async (client) => {
    await completeJob(client, job);
  });
}

async function run(signal: AbortSignal): Promise<void> {
  let lastLeaseRecovery = 0;
  while (!signal.aborted) {
    if (Date.now() - lastLeaseRecovery > 30_000) {
      await recoverExpiredJobLeases('privacy');
      lastLeaseRecovery = Date.now();
    }
    const job = await claimJob<ErasureJobPayload>('privacy', workerId, 120);
    if (!job) {
      await new Promise((resolve) => setTimeout(resolve, 250));
      continue;
    }
    try {
      await processJob(job);
    } catch (error) {
      logger.error({ error, jobId: job.id }, 'erasure job failed');
      await transaction(async (client) => {
        await failJob(client, job, error);
      });
    }
  }
}

void run(controller.signal);
logger.info({ workerId }, 'erasure worker started');
for (const signal of ['SIGTERM', 'SIGINT'] as const) {
  process.on(signal, () => controller.abort());
}
"}

