{"command":"create","path":"/workspace/source/tests/erasure-redaction.test.ts","file_text":"import assert from 'node:assert/strict';
import test from 'node:test';
import {
  ERASED_EMAIL,
  ERASED_NAME,
  anonymizedCustomerSnapshot,
  scrubJsonValue,
} from '../packages/privacy/src/redaction.js';

test('anonymized customer snapshot removes identifying fields', () => {
  const customerId = '147790aa-64d8-4f18-a650-1b3b006ed06e';
  const snapshot = anonymizedCustomerSnapshot(customerId);
  assert.equal(snapshot.email, ERASED_EMAIL);
  assert.equal(snapshot.name, ERASED_NAME);
  assert.equal(snapshot.status, 'erased');
  assert.equal(snapshot.external_reference, `erased:${customerId}`);
});

test('scrubJsonValue redacts nested personal fields while keeping structure', () => {
  const scrubbed = scrubJsonValue({
    customerId: 'abc',
    amount: 1200,
    customerEmail: 'person@example.test',
    nested: { billingName: 'Ada', city: 'London', total: 5 },
  }) as Record<string, unknown>;
  assert.equal(scrubbed.amount, 1200);
  assert.equal(scrubbed.customerEmail, ERASED_EMAIL);
  const nested = scrubbed.nested as Record<string, unknown>;
  assert.equal(nested.billingName, ERASED_NAME);
  assert.equal(nested.total, 5);
});
"}

