export const ERASED_EMAIL_DOMAIN = 'customer.invalid';
export const ERASED_NAME = 'Erased Customer';
export const ERASED_PHONE = null;
export const ERASED_EXTERNAL_REFERENCE_PREFIX = 'erased:';
export const ERASED_TEXT = '[erased]';
export const ERASED_POSTAL = '00000';
export const ERASED_COUNTRY = 'XX';

/** Per-customer erased email so unique(merchant_id,email) remains satisfied. */
export function erasedEmail(customerId: string): string {
  return `erased+${customerId}@${ERASED_EMAIL_DOMAIN}`;
}

/** @deprecated generic placeholder; prefer erasedEmail(customerId) when a row is customer-scoped. */
export const ERASED_EMAIL = `erased@${ERASED_EMAIL_DOMAIN}`;

export function erasedExternalReference(customerId: string): string {
  return `${ERASED_EXTERNAL_REFERENCE_PREFIX}${customerId}`;
}

export function isErasedEmail(value: string | null | undefined): boolean {
  if (!value) return false;
  return value.endsWith(`@${ERASED_EMAIL_DOMAIN}`) || value === ERASED_EMAIL;
}

export function anonymizedCustomerSnapshot(customerId: string): Record<string, unknown> {
  return {
    id: customerId,
    email: erasedEmail(customerId),
    name: ERASED_NAME,
    phone: ERASED_PHONE,
    external_reference: erasedExternalReference(customerId),
    status: 'erased',
    metadata: {},
  };
}"}

